WITH flattened_attrs AS (SELECT id, created_at, coupon_codes, items, TRY_CAST(attributes['weight_kg'] AS DOUBLE) AS weight_kg, TRANSFORM(FILTER(items, i -> i.promo IS NOT NULL), i -> STRUCT(i.product_id AS pid, ROUND(i.price * 0.9, 2) AS discounted_price)) AS promo_lines, ARRAY_MAX(TRANSFORM(items, i -> i.price)) AS max_item_price, COALESCE(attributes['device'], 'direct') AS device_or_default FROM carts) SELECT *, LEAD(max_item_price, 2) OVER (ORDER BY max_item_price, id) AS next_max_item_price, LAST_VALUE(weight_kg) IGNORE NULLS OVER (ORDER BY weight_kg, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_weight_kg, RANK() OVER (ORDER BY weight_kg DESC NULLS LAST) AS weight_kg_rank FROM flattened_attrs;
